.shft-wm{container-type:inline-size;width:100%;margin-top:clamp(20px,2.4vw,40px);overflow:hidden}
.shft-word{margin:0;line-height:.86;color:var(--sh-fg);white-space:nowrap;padding:.02em 0 .1em;user-select:none}
.shft-fit{display:inline-block;font-size:calc(100cqw / (var(--n) * .58));white-space:nowrap}
.shft-ch{position:relative;display:inline-block} .shft-sp{display:inline-block;width:.22em}
.shft-ch-f{transition:opacity .18s linear} .shft-word.is-wait .shft-ch-f{opacity:0} .shft-ch.is-g .shft-ch-f{opacity:0}
.shft-ch-g{position:absolute;left:50%;top:50%;translate:-50% -50%;font-family:var(--sh-fm,var(--sh-font-m,'JetBrains Mono'),ui-monospace,'SF Mono',Menlo,monospace);font-size:.62em;font-weight:500;letter-spacing:0;line-height:1;color:var(--sh-acc)}
/* tablet */
.shft.is-tb .shft-top{grid-template-columns:minmax(0,1fr);gap:52px} .shft.is-tb .shft-cols{justify-content:start;gap:56px}
/* phone: two columns of links, the meta lines stack */
.shft.is-ph .shft-in{padding-top:60px;padding-bottom:20px} .shft.is-ph.is-bar .shft-in{padding-bottom:204px}
.shft.is-ph .shft-top{grid-template-columns:minmax(0,1fr);gap:44px} .shft.is-ph .shft-line{font-size:27px} .shft.is-ph .shft-mail-a{font-size:17px}
.shft.is-ph .shft-cols{grid-auto-flow:row;grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-columns:auto;gap:36px 20px} .shft.is-ph .shft-col a{min-height:44px}
.shft.is-ph .shft-meta{display:grid;justify-content:start;margin-top:44px;gap:10px}


.sh-cur{position:fixed;z-index:9990;left:0;top:0;display:flex;align-items:center;gap:10px;pointer-events:none;opacity:0;transition:opacity .25s} .sh-cur.is-on{opacity:1}
.sh-cur i{display:block;width:12px;height:12px;margin:-6px 0 0 -6px;border-radius:50%;background:var(--sh-brass,#C6FF3D);box-shadow:0 0 0 1.5px var(--sh-night,#060708);transition:scale .25s cubic-bezier(.2,.8,.2,1)} .sh-cur.is-press i{scale:.6}
.sh-cur span{margin-top:-6px;padding:6px 9px;border-radius:7px;background:var(--sh-ink,#F1F2EC);color:var(--sh-night,#060708);font-size:11px;font-weight:500;line-height:1;white-space:nowrap}
html.sh-has-cur .sh-sec,html.sh-has-cur .sh-sec *{cursor:none}
